function icon(string $name='grid'): string {
 $paths=['grid'=>'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','chart'=>'M4 20V4 M4 20h17 M8 16l4-6 4 3 5-9','book'=>'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3z M12 6v15','people'=>'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-3a4 4 0 0 0-3-4 M16 3a4 4 0 0 1 0 8','star'=>'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z','alert'=>'m12 3 10 18H2z M12 9v5 M12 17v1','brain'=>'M9 4a4 4 0 0 0-6 4v1a4 4 0 0 0 0 7v1a4 4 0 0 0 6 3 M15 4a4 4 0 0 1 6 4v1a4 4 0 0 1 0 7v1a4 4 0 0 1-6 3 M12 3v18 M5 10h3v4 M19 10h-3v4','report'=>'M6 2h9l5 5v15H6z M14 2v6h6 M9 12h8 M9 16h8','data'=>'M3 6c0-5 18-5 18 0s-18 5-18 0 M3 6v12c0 5 18 5 18 0V6 M3 12c0 5 18 5 18 0','help'=>'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0','settings'=>'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2','home'=>'m3 10 9-8 9 8 M5 9v13h14V9 M9 22v-8h6v8','menu'=>'M3 6h18 M3 12h18 M3 18h18'];
 return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'.($paths[$name]??$paths['grid']).'"/></svg>';
