function brand(): void {echo '<a class="brand" href="index.php" aria-label="EduPulse home"><span class="brand-mark">'.icon('chart').'</span><span>Edu<span class="brand-accent">Pulse</span></span></a>';}
function head(string $title): void {echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#991b32"><title>'.h($title).' · EduPulse</title><link rel="stylesheet" href="assets/style.css?v=3"><script src="assets/interactions.js?v=3" defer></script><script src="assets/workspace.js?v=3" defer></script></head>' ;}
function workspaceStart(string $module,string $title,array $f=[]): void {
 head($title);echo '<body class="workspace"><a class="skip-link" href="#main">Skip to content</a><div class="drawer-shade" data-drawer-close></div><aside class="sidebar" id="sidebar" aria-label="Workspace navigation"><div class="sidebar-brand">';brand();echo '<button class="icon-button drawer-close" data-drawer-close aria-label="Close navigation">×</button></div>';
 $groups=['MAIN'=>[['overview','Intelligence Overview','grid'],['programs','CICS Programs','book'],['subjects','Subject Analytics','book'],['students','Student Performance','people'],['teaching','Teaching Effectiveness','star'],['trends','Academic Trends','chart']],'INTELLIGENCE'=>[['warnings','Early Warning System','alert'],['predict','ML Risk Explorer','brain'],['insights','Academic Insights','chart']],'MANAGEMENT'=>[['reports','Academic Reports','report'],['datasets','Dataset Management','data']],'SUPPORT'=>[['guide','Dashboard Guide','help'],['settings','Settings','settings'],['home','Back to Home','home']]];
 foreach($groups as $label=>$links){echo '<div class="side-caption">'.$label.'</div>';foreach($links as [$key,$text,$ico]){$url=$key==='home'?'index.php':($key==='predict'?'predict.php':'dashboard.php?'.($f?filterQuery($f,['module'=>$key]):http_build_query(['module'=>$key])));echo '<a aria-label="'.h($text).'" title="'.h($text).'" class="side-link '.($module===$key?'active':'').'" href="'.h($url).'" '.($module===$key?'aria-current="page"':'').'>'.icon($ico).'<span>'.$text.'</span></a>';}}
 echo '<div class="sidebar-bottom"><span class="workspace-avatar">PC</span><div><strong>Program Chair Workspace</strong><small>Public · read-only analytics</small></div></div></aside><main class="main" id="main"><div class="workspace-toolbar"><button class="icon-button" id="sidebarToggle" aria-controls="sidebar" aria-expanded="true" aria-label="Toggle navigation">'.icon('menu').'</button><span>College of Informatics and Computing Sciences</span><a href="index.php">Home</a></div><header class="topbar" id="tour-welcome"><div><p class="breadcrumb">Workspace / '.h($title).'</p><h1>'.h($title).'</h1><p class="subtitle">Academic intelligence for thoughtful decisions.</p></div><button class="btn-secondary" type="button" data-tour-start>'.icon('help').' Take a Tour</button></header>';
}
function workspaceEnd(): void {echo '<footer>EduPulse · BAT 405 Case Study · CICS academic project<br>Synthetic academic data and illustrative curriculum. Not an officially deployed or endorsed Batangas State University system.</footer></main><dialog id="tourDialog" class="tour-dialog" aria-labelledby="tourTitle" aria-describedby="tourText"><button class="tour-close icon-button" type="button" aria-label="Close tour">×</button><p id="tourProgress" class="eyebrow"></p><h2 id="tourTitle"></h2><p id="tourText"></p><div class="tour-controls"><button type="button" class="btn-quiet" data-tour-skip>Skip</button><button type="button" class="btn-secondary" data-tour-prev>Previous</button><button type="button" class="btn-primary" data-tour-next>Next</button></div></dialog></body></html>';}
function filterPanel(array $f,string $module): void { ?>
<section class="filter-panel" id="tour-filters"><div class="filter-intro"><strong>Analytics scope</strong><span class="data-pill">Synthetic data</span></div><form class="filters" method="get" action="dashboard.php"><input type="hidden" name="module" value="<?=h($module)?>"><label>Academic year<select name="year"><?php foreach($f['years'] as $v):?><option <?=$v===$f['year']?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></label><label>Semester<select name="semester"><?php foreach(['1st Semester','2nd Semester'] as $v):?><option <?=$v===$f['sem']?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></label><label>CICS program<select name="program"><option value="">All CICS programs</option><?php foreach($f['programs'] as $p):?><option value="<?=h($p['code'])?>" <?=$p['code']===$f['program']?'selected':''?>><?=h($p['code'])?></option><?php endforeach;?></select></label><label>Year level<select name="level"><option value="">All year levels</option><?php foreach(range(1,4) as $v):?><option value="<?=$v?>" <?=(string)$v===$f['level']?'selected':''?>>Year <?=$v?></option><?php endforeach;?></select></label><label>Subject<select name="subject" id="subjectFilter"><option value="">All subjects</option><?php foreach($f['subjects'] as $s):?><option value="<?=$s['id']?>" <?=(string)$s['id']===$f['subject']?'selected':''?>><?=h($s['code'].' · '.$s['title'])?></option><?php endforeach;?></select></label><button class="btn-primary" type="submit">Apply Filters</button><a class="btn-quiet" href="dashboard.php?module=<?=h($module)?>">Reset Filters</a></form><p class="scope-caption"><?=h($f['year'].' · '.$f['sem'].' · '.($f['program']?:'All CICS programs').($f['level']?' · Year '.$f['level']:'').($f['subject']?' · Selected subject':''))?></p></section>
<?php }
function kpiCards(array $metrics): void {echo '<section class="kpi-grid" id="tour-kpis">';foreach($metrics as $i=>$m){echo '<article class="kpi-card"><div class="kpi-head"><span>'.h($m['label']).'</span>'.icon(['chart','alert','star','people','report'][$i]).'</div><div class="kpi-value">'.h($m['value']).'</div><div class="kpi-foot"><span class="status '.($m['raw']===null?'neutral':($m['low']?'warning':'ok')).'">'.($m['raw']===null?'Unavailable':($m['low']?'Needs attention':'On target')).'</span><span>Target '.h($m['target']).'</span></div></article>'; }echo '</section>';}
function chartCard(string $id,string $title,string $description,bool $wide=false,string $tour=''): void {echo '<article class="chart-card '.($wide?'wide':'').'" '.($tour?'id="'.h($tour).'"':'').'><div class="chart-title"><h3>'.h($title).'</h3><p>'.h($description).'</p></div><div class="chart-area"><canvas id="'.h($id).'" role="img" aria-label="'.h($title).'"></canvas></div></article>';}
function dataTable(array $rows,string $caption,array $f=[],bool $subjectLinks=false): void {
 echo '<section class="chart-card data-section"><div class="table-heading"><h2>'.h($caption).'</h2><label class="table-search">Search <input type="search" placeholder="Search this table" data-table-search></label></div><p class="hint">Select a column heading to sort. Values are for the active filter scope.</p><div class="table-scroll"><table><caption class="sr-only">'.h($caption).'</caption>';
 if(!$rows){echo '<tbody><tr><td>No records match this scope. Try resetting the filters.</td></tr></tbody></table></div></section>';return;}
 $keys=array_values(array_filter(array_keys($rows[0]),fn($key)=>$key!=='id'));echo '<thead><tr>';foreach($keys as $key)echo '<th scope="col"><button type="button" class="sort-button">'.h($key).'<span aria-hidden="true"> ↕</span></button></th>';echo '</tr></thead><tbody>';
 foreach($rows as $row){echo '<tr>';foreach($keys as $key){echo '<td>';if($subjectLinks&&$key==='Subject')echo '<a href="dashboard.php?'.h(filterQuery($f,['module'=>'subjects','subject'=>$row['id']])).'">'.h($row[$key]).'</a>';else echo h($row[$key]??'No data');echo '</td>';}echo '</tr>';}echo '</tbody></table><p class="table-empty" hidden>No matching rows.</p></div></section>';
}
function insights(array $metrics): void {echo '<article class="insight-card" id="tour-warnings"><p class="eyebrow">EARLY WARNING SYSTEM</p><h2>Signals worth a closer look</h2>'; $count=0;foreach($metrics as $m)if($m['low']){$count++;echo '<div class="alert">'.icon('alert').'<span>'.h($m['label'].' is outside the proposed target ('.$m['value'].').').'</span></div>';}if(!$count)echo '<p>No out-of-target signals among available KPIs.</p>';echo '<p class="hint">Rule-based flags: average grade above 3 or attendance below 75%. Proposed classroom thresholds, not university policy.</p></article>';}
